  KEY `idx_cantidad_oficina` (`cantidad_oficina`),
  CONSTRAINT `fk_i_area_actual` FOREIGN KEY (`id_area_asignacion_actual`) REFERENCES `areas` (`id_area`) ON DELETE SET NULL,
